func (s *ElectronicSpeedControllerOpsServiceHandler) DeleteElectronicSpeedController(ctx context.Context, req *connect.Request[DeleteElectronicSpeedControllerOpsRequest]) (*connect.Response[DeleteElectronicSpeedControllerOpsResponse], error) {
	idOrUUID := strings.TrimSpace(req.Msg.GetId())
	if idOrUUID == "" {
		return nil, connect.NewError(connect.CodeInvalidArgument, errors.New("id is required"))
	}

	var existingUUID string
	err := s.db.QueryRow(ctx, "SELECT uuid::text FROM entities WHERE collection = $1 AND (id = $2 OR uuid::text = $2)", "electronic-speed-controllers", idOrUUID).Scan(&existingUUID)
	if err != nil {
		if errors.Is(err, pgx.ErrNoRows) {
			return nil, connect.NewError(connect.CodeNotFound, errors.New("electronicspeedcontroller not found"))
		}
		return nil, connect.NewError(connect.CodeInternal, err)
	}

	tx, err := s.db.Begin(ctx)
	if err != nil {
		return nil, connect.NewError(connect.CodeInternal, err)
	}
	defer tx.Rollback(ctx)

	var activityCount int64
	_ = tx.QueryRow(ctx, `
		SELECT (
			(SELECT count(*) FROM builds WHERE $1::uuid = ANY(electronic_speed_controller_uuids)) + (SELECT count(*) FROM flight_controllers WHERE internal_electronic_speed_controller_uuid = $1) +
			(SELECT count(*) FROM questions WHERE entity_uuid = $1) +
			(SELECT count(*) FROM reviews WHERE entity_uuid = $1) +
			(SELECT count(*) FROM collection_items WHERE entity_uuid = $1)
		)
	`, existingUUID).Scan(&activityCount)

	isArchived := false
	if activityCount == 0 {
		if _, err := tx.Exec(ctx, "DELETE FROM blob_references WHERE entity_type = $1 AND entity_uuid = $2", "electronic-speed-controllers", existingUUID); err != nil {
			return nil, connect.NewError(connect.CodeInternal, fmt.Errorf("failed to delete blob references: %w", err))
		}
		if _, err := tx.Exec(ctx, "DELETE FROM electronic_speed_controllers WHERE uuid = $1", existingUUID); err != nil {
			return nil, connect.NewError(connect.CodeInternal, fmt.Errorf("failed to delete from electronic_speed_controllers: %w", err))
		}
		if _, err := tx.Exec(ctx, "DELETE FROM entities WHERE uuid = $1", existingUUID); err != nil {
			return nil, connect.NewError(connect.CodeInternal, fmt.Errorf("failed to delete entity: %w", err))
		}
	} else {
		isArchived = true
		if _, err := tx.Exec(ctx, "UPDATE entities SET is_archived = true, updated_at = NOW() WHERE uuid = $1", existingUUID); err != nil {
			return nil, connect.NewError(connect.CodeInternal, fmt.Errorf("failed to archive entity: %w", err))
		}
	}

	if err := tx.Commit(ctx); err != nil {
		return nil, connect.NewError(connect.CodeInternal, err)
	}

	return connect.NewResponse(&DeleteElectronicSpeedControllerOpsResponse{IsArchived: isArchived}), nil
}

