func (s *EscFirmwareOpsServiceHandler) ListEscFirmwares(ctx context.Context, req *connect.Request[ListEscFirmwaresOpsRequest]) (*connect.Response[ListEscFirmwaresOpsResponse], error) {
	pageSize, err := pagination.ParsePageSize(req.Msg.GetPageSize())
	if err != nil {
		return nil, connect.NewError(connect.CodeInvalidArgument, err)
	}

	filter, sort, offset, err := pagination.ResolveParams(req.Msg.GetFilter(), req.Msg.GetSort(), req.Msg.GetPageToken())
	if err != nil {
		return nil, connect.NewError(connect.CodeInvalidArgument, err)
	}

	where, args, err := cel2sql.Compile(filter)
	if err != nil {
		return nil, connect.NewError(connect.CodeInvalidArgument, err)
	}

	includeArchived := req.Msg.GetIncludeArchived() || strings.Contains(filter, "is_archived")
	items, err := apipb.ListEscFirmwaresIncludingArchived(ctx, s.db, includeArchived, req.Msg.GetColumns(), sort, where, pageSize+1, offset, args...)
	if err != nil {
		if pagination.IsInvalidArgument(err) {
			return nil, connect.NewError(connect.CodeInvalidArgument, err)
		}
		return nil, connect.NewError(connect.CodeInternal, errors.New("an internal error occurred"))
	}

	nextPageToken := ""
	if int32(len(items)) > pageSize {
		items = items[:pageSize]
		nextPageToken, err = pagination.EncodePageToken(offset+pageSize, filter, sort)
		if err != nil {
			return nil, connect.NewError(connect.CodeInternal, err)
		}
	}

	res := &ListEscFirmwaresOpsResponse{
		EscFirmwares:  items,
		NextPageToken: nextPageToken,
	}
	return connect.NewResponse(res), nil
}

