	defer tx.Rollback(ctx)

	var idExists bool
	if err := tx.QueryRow(ctx, "SELECT EXISTS(SELECT 1 FROM entities WHERE collection = $1 AND id = $2)", "flight-controllers", m.Id).Scan(&idExists); err != nil {
		return nil, connect.NewError(connect.CodeInternal, fmt.Errorf("failed to check id existence: %w", err))
	}
	if idExists {
		newID, err := buildid.NextCopyID(m.Id, func(cand string) (bool, error) {
			var exists bool
			err := tx.QueryRow(ctx, "SELECT EXISTS(SELECT 1 FROM entities WHERE collection = $1 AND id = $2)", "flight-controllers", cand).Scan(&exists)
			return exists, err
		})
		if err != nil {
			return nil, connect.NewError(connect.CodeInternal, fmt.Errorf("failed to generate unique id: %w", err))
		}
		m.Id = newID
	}

	var refLinksJSON, mediaJSON []byte
