	if _, err := tx.Exec(ctx, "DELETE FROM blob_references WHERE entity_type = $1 AND entity_uuid = $2", "gps-receivers", m.Uuid); err != nil {
		return nil, connect.NewError(connect.CodeInternal, fmt.Errorf("failed to clear old blob references: %w", err))
	}

	var blobURLs []string
