func (s *MotorOpsServiceHandler) DeleteMotor(ctx context.Context, req *connect.Request[DeleteMotorOpsRequest]) (*connect.Response[DeleteMotorOpsResponse], error) {
	idOrUUID := strings.TrimSpace(req.Msg.GetId())
	if idOrUUID == "" {
		return nil, connect.NewError(connect.CodeInvalidArgument, errors.New("id is required"))
	}

	var existingUUID string
	err := s.db.QueryRow(ctx, "SELECT uuid::text FROM entities WHERE collection = $1 AND (id = $2 OR uuid::text = $2)", "motors", idOrUUID).Scan(&existingUUID)
	if err != nil {
		if errors.Is(err, pgx.ErrNoRows) {
			return nil, connect.NewError(connect.CodeNotFound, errors.New("motor not found"))
		}
		return nil, connect.NewError(connect.CodeInternal, err)
	}

	tx, err := s.db.Begin(ctx)
	if err != nil {
		return nil, connect.NewError(connect.CodeInternal, err)
	}
	defer tx.Rollback(ctx)

	var activityCount int64
	_ = tx.QueryRow(ctx, `
		SELECT (
			(SELECT count(*) FROM builds WHERE motor_uuid = $1) +
			(SELECT count(*) FROM questions WHERE entity_uuid = $1) +
			(SELECT count(*) FROM reviews WHERE entity_uuid = $1) +
			(SELECT count(*) FROM collection_items WHERE entity_uuid = $1)
		)
	`, existingUUID).Scan(&activityCount)

	isArchived := false
	if activityCount == 0 {
		if _, err := tx.Exec(ctx, "DELETE FROM blob_references WHERE entity_type = $1 AND entity_uuid = $2", "motors", existingUUID); err != nil {
			return nil, connect.NewError(connect.CodeInternal, fmt.Errorf("failed to delete blob references: %w", err))
		}
		if _, err := tx.Exec(ctx, "DELETE FROM motors WHERE uuid = $1", existingUUID); err != nil {
			return nil, connect.NewError(connect.CodeInternal, fmt.Errorf("failed to delete from motors: %w", err))
		}
		if _, err := tx.Exec(ctx, "DELETE FROM entities WHERE uuid = $1", existingUUID); err != nil {
			return nil, connect.NewError(connect.CodeInternal, fmt.Errorf("failed to delete entity: %w", err))
		}
	} else {
		isArchived = true
		if _, err := tx.Exec(ctx, "UPDATE entities SET is_archived = true, updated_at = NOW() WHERE uuid = $1", existingUUID); err != nil {
			return nil, connect.NewError(connect.CodeInternal, fmt.Errorf("failed to archive entity: %w", err))
		}
	}

	if err := tx.Commit(ctx); err != nil {
		return nil, connect.NewError(connect.CodeInternal, err)
	}

	return connect.NewResponse(&DeleteMotorOpsResponse{IsArchived: isArchived}), nil
}

func (s *MotorOpsServiceHandler) RestoreMotor(ctx context.Context, req *connect.Request[RestoreMotorOpsRequest]) (*connect.Response[apipb.Motor], error) {
	idOrUUID := strings.TrimSpace(req.Msg.GetId())
	if idOrUUID == "" {
		return nil, connect.NewError(connect.CodeInvalidArgument, errors.New("id is required"))
	}

	var existingUUID string
	err := s.db.QueryRow(ctx, "SELECT uuid::text FROM entities WHERE collection = $1 AND (id = $2 OR uuid::text = $2)", "motors", idOrUUID).Scan(&existingUUID)
	if err != nil {
		if errors.Is(err, pgx.ErrNoRows) {
			return nil, connect.NewError(connect.CodeNotFound, errors.New("motor not found"))
		}
		return nil, connect.NewError(connect.CodeInternal, err)
	}

	if _, err := s.db.Exec(ctx, "UPDATE entities SET is_archived = false, updated_at = NOW() WHERE uuid = $1", existingUUID); err != nil {
		return nil, connect.NewError(connect.CodeInternal, fmt.Errorf("failed to restore entity: %w", err))
	}

	restored, err := apipb.GetMotor(ctx, s.db, existingUUID, nil)
	if err != nil {
		return nil, connect.NewError(connect.CodeInternal, err)
	}
	return connect.NewResponse(restored), nil
}

