func (s *RadioFirmwareOpsServiceHandler) ListRadioFirmwares(ctx context.Context, req *connect.Request[ListRadioFirmwaresOpsRequest]) (*connect.Response[ListRadioFirmwaresOpsResponse], error) {
	pageSize, err := pagination.ParsePageSize(req.Msg.GetPageSize())
	if err != nil {
		return nil, connect.NewError(connect.CodeInvalidArgument, err)
	}

	filter, sort, offset, err := pagination.ResolveParams(req.Msg.GetFilter(), req.Msg.GetSort(), req.Msg.GetPageToken())
	if err != nil {
		return nil, connect.NewError(connect.CodeInvalidArgument, err)
	}

	where, args, err := cel2sql.Compile(filter)
	if err != nil {
		return nil, connect.NewError(connect.CodeInvalidArgument, err)
	}

	includeArchived := req.Msg.GetIncludeArchived() || strings.Contains(filter, "is_archived")
	items, err := apipb.ListRadioFirmwaresIncludingArchived(ctx, s.db, includeArchived, req.Msg.GetColumns(), sort, where, pageSize+1, offset, args...)
	if err != nil {
		if pagination.IsInvalidArgument(err) {
			return nil, connect.NewError(connect.CodeInvalidArgument, err)
		}
		return nil, connect.NewError(connect.CodeInternal, errors.New("an internal error occurred"))
	}

	nextPageToken := ""
	if int32(len(items)) > pageSize {
		items = items[:pageSize]
		nextPageToken, err = pagination.EncodePageToken(offset+pageSize, filter, sort)
		if err != nil {
			return nil, connect.NewError(connect.CodeInternal, err)
		}
	}

	res := &ListRadioFirmwaresOpsResponse{
		RadioFirmwares: items,
		NextPageToken:  nextPageToken,
	}
	return connect.NewResponse(res), nil
}

func (s *RadioFirmwareOpsServiceHandler) CreateRadioFirmware(ctx context.Context, req *connect.Request[CreateRadioFirmwareOpsRequest]) (*connect.Response[apipb.RadioFirmware], error) {
	m := req.Msg.GetRadioFirmware()
	if m == nil {
		return nil, connect.NewError(connect.CodeInvalidArgument, errors.New("radiofirmware object is required"))
	}

	if strings.TrimSpace(m.Name) == "" {
		return nil, connect.NewError(connect.CodeInvalidArgument, errors.New("name is required"))
	}
	if len(m.Name) > 256 {
		return nil, connect.NewError(connect.CodeInvalidArgument, errors.New("name exceeds maximum length of 256 characters"))
	}
	if strings.TrimSpace(m.Manufacturer) == "" {
		return nil, connect.NewError(connect.CodeInvalidArgument, errors.New("manufacturer is required"))
	}
	if len(m.Manufacturer) > 128 {
		return nil, connect.NewError(connect.CodeInvalidArgument, errors.New("manufacturer exceeds maximum length of 128 characters"))
	}
	if err := apipb.ValidateReferenceLinks(m.ReferenceLinks); err != nil {
		return nil, connect.NewError(connect.CodeInvalidArgument, err)
	}

	m.Uuid = authcontext.NewUUIDv7()
	m.IsArchived = false

	if m.Id == "" {
		base := strings.TrimSpace(m.Manufacturer + " " + m.Name)
		if base == "" {
			base = m.Name
		}
		reg := regexp.MustCompile("[^a-z0-9]+")
		slug := strings.Trim(reg.ReplaceAllString(strings.ToLower(base), "-"), "-")
		if slug == "" {
			slug = "radio-firmware-" + m.Uuid[:8]
		}
		m.Id = slug
	} else {
		m.Id = strings.ToLower(strings.TrimSpace(m.Id))
		uuidRegex := regexp.MustCompile(`^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$`)
		if uuidRegex.MatchString(m.Id) {
			return nil, connect.NewError(connect.CodeInvalidArgument, errors.New("custom id cannot be formatted as a UUID"))
		}
	}

	tx, err := s.db.Begin(ctx)
	if err != nil {
		return nil, connect.NewError(connect.CodeInternal, err)
	}
	defer tx.Rollback(ctx)

	var idExists bool
	if err := tx.QueryRow(ctx, "SELECT EXISTS(SELECT 1 FROM entities WHERE collection = $1 AND id = $2)", "radio-firmware", m.Id).Scan(&idExists); err != nil {
		return nil, connect.NewError(connect.CodeInternal, fmt.Errorf("failed to check id existence: %w", err))
	}
	if idExists {
		newID, err := buildid.NextCopyID(m.Id, func(cand string) (bool, error) {
			var exists bool
			err := tx.QueryRow(ctx, "SELECT EXISTS(SELECT 1 FROM entities WHERE collection = $1 AND id = $2)", "radio-firmware", cand).Scan(&exists)
			return exists, err
		})
		if err != nil {
			return nil, connect.NewError(connect.CodeInternal, fmt.Errorf("failed to generate unique id: %w", err))
		}
		m.Id = newID
	}

	var refLinksJSON, mediaJSON []byte
	if len(m.ReferenceLinks) > 0 {
		refLinksJSON, _ = json.Marshal(m.ReferenceLinks)
	}
	if len(m.Media) > 0 {
		mediaJSON, _ = json.Marshal(m.Media)
	}
	authorOrMfr := m.Manufacturer
	sysUserUUID := authcontext.SystemUserUUID
	_, err = tx.Exec(ctx, `
		INSERT INTO entities (uuid, collection, id, name, description, primary_display_image, reference_links, media, author_or_manufacturer, user_uuid, is_archived, created_at, updated_at)
		VALUES ($1, 'radio-firmware', $2, $3, $4, $5, $6, $7, $8, $9, false, NOW(), NOW())
		ON CONFLICT (collection, id) DO UPDATE
		SET name = EXCLUDED.name, description = EXCLUDED.description, primary_display_image = EXCLUDED.primary_display_image, author_or_manufacturer = EXCLUDED.author_or_manufacturer, user_uuid = EXCLUDED.user_uuid, updated_at = NOW()
	`, m.Uuid, m.Id, m.Name, m.Description, m.PrimaryDisplayImage, refLinksJSON, mediaJSON, authorOrMfr, &sysUserUUID)
	if err != nil {
		return nil, connect.NewError(connect.CodeInternal, fmt.Errorf("failed to save entity: %w", err))
	}

	if err := apipb.CreateRadioFirmware(ctx, tx, m); err != nil {
		return nil, connect.NewError(connect.CodeInternal, fmt.Errorf("failed to save radio_firmwares: %w", err))
	}

	var blobURLs []string
	if m.PrimaryDisplayImage != nil && *m.PrimaryDisplayImage != "" {
		blobURLs = append(blobURLs, *m.PrimaryDisplayImage)
	}
	for _, item := range m.Media {
		if item != nil && item.Url != "" {
			blobURLs = append(blobURLs, item.Url)
		}
	}
	blobRegex := regexp.MustCompile(`(?i)(?:^|/blobs/)([a-f0-9]{64}|[a-f0-9]{8}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{12})`)
	for _, u := range blobURLs {
		if matches := blobRegex.FindStringSubmatch(strings.TrimSpace(u)); len(matches) > 1 {
			key := strings.ToLower(matches[1])
			refUUID := authcontext.NewUUIDv7()
			if _, err := tx.Exec(ctx, `
				INSERT INTO blob_references (uuid, id, blob_uuid, entity_type, entity_uuid, created_at)
				SELECT $1::uuid, 'ref-' || $1::text, b.uuid, $2, $3::uuid, NOW()
				FROM blobs b
				WHERE b.id = $4 OR b.uuid::text = $4
				ON CONFLICT (blob_uuid, entity_type, entity_uuid) DO NOTHING;`,
				refUUID, "radio-firmware", m.Uuid, key); err != nil {
				return nil, connect.NewError(connect.CodeInternal, fmt.Errorf("failed to link blob reference: %w", err))
			}
		}
	}

	if err := tx.Commit(ctx); err != nil {
		return nil, connect.NewError(connect.CodeInternal, err)
	}

	created, err := apipb.GetRadioFirmware(ctx, s.db, m.Uuid, nil)
	if err != nil {
		return connect.NewResponse(m), nil
	}
	return connect.NewResponse(created), nil
}

